configuration.jsScript:
// ===== SMARTHOME AUTOMATION CONDITION EVALUATOR =====
// metadata.originatorId = device UUID (lay tu TbGetOriginatorFieldsNode)
// metadata.homeAutomations = JSON string cua automation rules tu Home Asset

var automations;
try {
    automations = JSON.parse(metadata.homeAutomations || '[]');
} catch(e) {
    return {msg: msg, metadata: metadata, msgType: 'PARSE_ERROR'};
}

var now = new Date();
var currentHour = now.getHours();
var currentMinute = now.getMinutes();
var currentTimeMin = currentHour * 60 + currentMinute;
var currentDay = now.getDay() === 0 ? 7 : now.getDay(); // 1=Mon, 7=Sun

var triggered = [];

for (var i = 0; i < automations.length; i++) {
    var rule = automations[i];
    if (!rule.enabled) continue;
    if (rule.execution_target && rule.execution_target.indexOf('gateway:') === 0) continue;

    // Check effective period
    if (rule.extra && rule.extra.effective_period && rule.extra.effective_period.type === 'custom') {
        var ep = rule.extra.effective_period;
        if (ep.days && ep.days.indexOf(currentDay) === -1) continue;
        if (ep.from && ep.to) {
            var epF = ep.from.split(':');
            var epT = ep.to.split(':');
            var epFrom = parseInt(epF[0]) * 60 + parseInt(epF[1]);
            var epTo   = parseInt(epT[0]) * 60 + parseInt(epT[1]);
            if (currentTimeMin < epFrom || currentTimeMin > epTo) continue;
        }
    }

    var results = [];
    var hasRelevantDeviceCond = false;

    for (var j = 0; j < rule.conditions.length; j++) {
        var cond = rule.conditions[j];
        var met = false;

        if (cond.type === 'device_state') {
            // So sanh device_id voi originatorId (ca hai deu la UUID)
            if (cond.device_id === metadata.originatorId) {
                hasRelevantDeviceCond = true;
                var val = msg[cond.attribute];
                if (val !== undefined && val !== null) {
                    var cv = cond.value;
                    switch (cond.operator) {
                        case '>':  met = val > cv; break;
                        case '<':  met = val < cv; break;
                        case '>=': met = val >= cv; break;
                        case '<=': met = val <= cv; break;
                        case '==': met = String(val) === String(cv); break;
                        case '!=': met = String(val) !== String(cv); break;
                    }
                }
            } else {
                // Device khac - khong co data hien tai, skip condition nay
                met = false;
            }
        } else if (cond.type === 'time_range') {
            var f = cond.from.split(':');
            var t = cond.to.split(':');
            var from = parseInt(f[0]) * 60 + parseInt(f[1]);
            var to   = parseInt(t[0]) * 60 + parseInt(t[1]);
            if (from <= to) {
                met = currentTimeMin >= from && currentTimeMin <= to;
            } else {
                met = currentTimeMin >= from || currentTimeMin <= to;
            }
        } else if (cond.type === 'time_schedule') {
            if (cond.cron) {
                var parts = cond.cron.split(' ');
                if (parts.length >= 2) {
                    var cm = parts[0] === '*' ? currentMinute : parseInt(parts[0]);
                    var ch = parts[1] === '*' ? currentHour   : parseInt(parts[1]);
                    met = currentHour === ch && currentMinute === cm;
                }
            }
        } else if (cond.type === 'day_of_week') {
            met = cond.days && cond.days.indexOf(currentDay) !== -1;
        }

        results.push(met);
    }

    // Neu rule co device_state condition nhung khong lien quan den device hien tai -> skip
    var hasAnyDeviceCond = rule.conditions.some(function(c) { return c.type === 'device_state'; });
    if (hasAnyDeviceCond && !hasRelevantDeviceCond) continue;

    var matched;
    if (rule.condition_match === 'any') {
        matched = results.some(function(v) { return v; });
    } else {
        matched = results.length > 0 && results.every(function(v) { return v; });
    }

    if (matched) {
        triggered.push({
            ruleId: rule.id,
            ruleName: rule.name,
            actions: rule.actions
        });
    }
}

if (triggered.length > 0) {
    var out = {
        triggeredRules: triggered,
        triggerDeviceId: metadata.originatorId,
        triggerDeviceName: metadata.originatorName || metadata.deviceName,
        timestamp: now.getTime()
    };
    return {msg: out, metadata: metadata, msgType: 'AUTOMATION_TRIGGERED'};
}
return {msg: msg, metadata: metadata, msgType: 'NO_MATCH'};

// Lay action dau tien de thuc hien
// Luu tat ca actions vao metadata
var allActions = [];
for (var i = 0; i < msg.triggeredRules.length; i++) {
    var rule = msg.triggeredRules[i];
    for (var j = 0; j < rule.actions.length; j++) {
        var a = rule.actions[j];
        a._ruleId = rule.ruleId;
        a._ruleName = rule.ruleName;
        allActions.push(a);
    }
}
var newMeta = metadata;
newMeta.pendingActions = JSON.stringify(allActions);
newMeta.triggerDeviceId = msg.triggerDeviceId;
newMeta.triggerDeviceName = msg.triggerDeviceName;
newMeta.triggerTimestamp = String(msg.timestamp);

if (allActions.length > 0) {
    return {msg: allActions[0], metadata: newMeta, msgType: 'EXECUTE_ACTION'};
}
return {msg: msg, metadata: newMeta, msgType: 'NO_ACTIONS'};

switch (msg.type) {
    case 'device_command':    return ['device_command'];
    case 'delay':             return ['delay'];
    case 'send_notification': return ['notification'];
    default:                  return ['unknown'];
}

// Chuyen device_command action thanh RPC call format
// Luu ca device_id (UUID) va device_name (ten thiet bi) vao metadata.
// TbChangeOriginatorNode se dung device_name de tim va doi originator.
var rpc = {
    method: msg.command,
    params: msg.params || {}
};
var newMeta = metadata;
newMeta.targetDeviceId   = msg.device_id;
newMeta.targetDeviceName = msg.device_name || '';
newMeta.actionRuleId     = msg._ruleId;
newMeta.actionRuleName   = msg._ruleName;
return {msg: rpc, metadata: newMeta, msgType: 'RPC_CALL_FROM_SERVER_TO_DEVICE'};

configuration.alarmDetailsBuildJs:
var d = {};
d.message = msg.message || 'Automation triggered';
d.ruleName = msg._ruleName || '';
return d;

configuration.jsScript:
var log = {
    automation_log: JSON.stringify({
        rule_id:        metadata.actionRuleId || 'unknown',
        rule_name:      metadata.actionRuleName || 'unknown',
        triggered_at:   new Date().toISOString(),
        trigger_device: metadata.triggerDeviceName || metadata.triggerDeviceId || 'unknown',
        status:         'success'
    })
};
return {msg: log, metadata: metadata, msgType: 'POST_TELEMETRY_REQUEST'};

var log = {
    automation_log: JSON.stringify({
        rule_id:        metadata.actionRuleId || 'unknown',
        rule_name:      metadata.actionRuleName || 'unknown',
        triggered_at:   new Date().toISOString(),
        trigger_device: metadata.triggerDeviceName || 'unknown',
        status:         'failed',
        error:          'RPC call failed or timed out'
    })
};
return {msg: log, metadata: metadata, msgType: 'POST_TELEMETRY_REQUEST'};
